-- Create "payment_method_preferences" table
CREATE TABLE "payment_method_preferences" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "method" character varying NOT NULL,
  "is_recommended" boolean NOT NULL DEFAULT true,
  "version" bigint NOT NULL DEFAULT 1,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "payment_method_preferences_method_valid" CHECK (((method)::text = TRIM(BOTH FROM method)) AND ((length((method)::text) >= 1) AND (length((method)::text) <= 128))),
  CONSTRAINT "payment_method_preferences_version_positive" CHECK (version > 0)
);
-- Create index "payment_method_preferences_method_key" to table: "payment_method_preferences"
CREATE UNIQUE INDEX "payment_method_preferences_method_key" ON "payment_method_preferences" ("method");
